#include <vector>
#include <queue>
using namespace std;

class Solution {
public:
    int minMergeCost(vector<vector<int>>& lists) {
        if (lists.size() <= 1) return 0;
        priority_queue<int, vector<int>, greater<int>> pq;
        for (const auto& lst : lists) pq.push(lst.size());
        int total_cost = 0;
        while (pq.size() > 1) {
            int a = pq.top(); pq.pop();
            int b = pq.top(); pq.pop();
            int merged = a + b;
            total_cost += merged;
            pq.push(merged);
        }
        return total_cost;
    }
};

import java.util.*;

class Solution {
    public int minMergeCost(int[][] lists) {
        if (lists.length <= 1) return 0;
        PriorityQueue<Integer> pq = new PriorityQueue<>();
        for (int[] lst : lists) pq.offer(lst.length);
        int totalCost = 0;
        while (pq.size() > 1) {
            int a = pq.poll();
            int b = pq.poll();
            int merged = a + b;
            totalCost += merged;
            pq.offer(merged);
        }
        return totalCost;
    }
}

var minMergeCost = function(lists) {
    if (lists.length <= 1) return 0;
    const lengths = lists.map(lst => lst.length);
    let totalCost = 0;
    while (lengths.length > 1) {
        lengths.sort((a, b) => a - b);
        const a = lengths.shift();
        const b = lengths.shift();
        const merged = a + b;
        totalCost += merged;
        lengths.push(merged);
    }
    return totalCost;
};
